// Long erased runs only. Generic mode checks every byte; indexed mode checks
// aligned native pointers plus known packed bytecode fields. Guard each target.
export function erasedROMSpans(bytes,{packedPointerSites=null}={}){const refs=[],v=new DataView(bytes.buffer,bytes.byteOffset,bytes.byteLength);for(let at=0;at+4<=bytes.length;at++){if(packedPointerSites&&at%4&&!packedPointerSites.has(at))continue;const n=v.getUint32(at,true)-0x08000000;if(n>=512&&n<bytes.length)refs.push(n);}refs.sort((a,b)=>a-b);const spans=[];for(let at=512;at<bytes.length-40;){if(bytes[at]!==255){at++;continue;}const begin=at;while(at<bytes.length-40&&bytes[at]===255)at++;if(at-begin<4096)continue;let cursor=(begin+19)&~3;for(const n of refs){if(n<begin)continue;if(n>=at)break;const stop=Math.max(cursor,n-256);if(stop-cursor>=256)spans.push({start:cursor,end:stop});cursor=Math.max(cursor,(n+259)&~3);}if(at-16-cursor>=256)spans.push({start:cursor,end:at-16});}return spans;}
